package uk.ac.ravensbourne.casevault.web;
import static org.junit.jupiter.api.Assertions.*; import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.AdminAccountService; import uk.ac.ravensbourne.casevault.support.TestDataCleaner;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AdminSecurityTest { @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired OrganisationRepository orgs; @Autowired UserAccountRepository users; @Autowired CaseRepository cases; @Autowired AdminAccountService adminAccounts; @Autowired TestDataCleaner cleaner; UserAccount admin,otherAdmin,client,manager; CaseRecord caseRecord; @BeforeEach void data(){jdbc.update("DELETE FROM audit_events");jdbc.update("UPDATE audit_chain_head SET last_event_id=NULL,last_hash=NULL WHERE singleton=TRUE");cleaner.clean();Organisation internal=orgs.save(new Organisation(UUID.randomUUID(),"Internal"));Organisation external=orgs.save(new Organisation(UUID.randomUUID(),"External"));admin=save(internal,"admin@test",Role.AUDITOR_ADMIN);otherAdmin=save(internal,"admin2@test",Role.AUDITOR_ADMIN);manager=save(internal,"manager@test",Role.CASE_MANAGER);client=save(external,"client@test",Role.CLIENT_USER);caseRecord=cases.save(new CaseRecord(UUID.randomUUID(),external,"Case title","Synthetic",Category.OTHER,Severity.LOW,client));} @AfterEach void cleanFixtures(){cleaner.clean();} UserAccount save(Organisation o,String e,Role r){return users.save(new UserAccount(UUID.randomUUID(),o,e,"hash",r));} UsernamePasswordAuthenticationToken auth(UserAccount u){var p=UserPrincipal.from(u);return UsernamePasswordAuthenticationToken.authenticated(p,null,p.getAuthorities());}
@Test void tAdmin001OnlyAuditorCanAccessAdmin(){assertDoesNotThrow(()->mvc.perform(get("/admin/accounts").with(authentication(auth(admin)))).andExpect(status().isOk()));assertDoesNotThrow(()->mvc.perform(get("/admin/accounts").with(authentication(auth(manager)))).andExpect(status().isForbidden()));}
@Test void tAdmin002DisablingAccountKillsAccess(){assertDoesNotThrow(()->mvc.perform(post("/admin/accounts/{id}/disable",client.getId()).param("reason","test").with(authentication(auth(admin))).with(csrf())).andExpect(status().is3xxRedirection()));assertFalse(users.findById(client.getId()).orElseThrow().isEnabled());assertDoesNotThrow(()->mvc.perform(get("/cases").with(authentication(auth(users.findById(client.getId()).orElseThrow())))).andExpect(status().is3xxRedirection()));}
@Test void tAdmin003CannotDisableSelfOrLastAdmin(){assertThrows(IllegalArgumentException.class,()->adminAccounts.disable(UserPrincipal.from(admin),admin.getId(),"test"));assertTrue(users.findById(admin.getId()).orElseThrow().isEnabled());UserAccount disabled=users.findById(otherAdmin.getId()).orElseThrow();disabled.disable();users.save(disabled);assertThrows(IllegalArgumentException.class,()->adminAccounts.disable(UserPrincipal.from(otherAdmin),admin.getId(),"test"));assertTrue(users.findById(admin.getId()).orElseThrow().isEnabled());}
@Test void tAdmin004ActionsAreAuditedAndPasswordResetFlagged(){assertDoesNotThrow(()->mvc.perform(post("/admin/accounts/{id}/force-password-reset",client.getId()).param("reason","test").with(authentication(auth(admin))).with(csrf())).andExpect(status().is3xxRedirection()));assertTrue(users.findById(client.getId()).orElseThrow().isForcePasswordReset());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_events WHERE action='FORCE_PASSWORD_RESET'",Integer.class));assertDoesNotThrow(()->mvc.perform(get("/admin/audit").with(authentication(auth(admin)))).andExpect(status().isOk()));assertDoesNotThrow(()->mvc.perform(post("/admin/audit/verify").with(authentication(auth(admin))).with(csrf())).andExpect(status().isOk()));}
@Test void tAdmin005AdminCannotReadCaseContent(){assertDoesNotThrow(()->mvc.perform(get("/cases/{id}",caseRecord.getId()).with(authentication(auth(admin)))).andExpect(status().isNotFound()));}
@Test void tErr001GenericErrorHasCorrelationId() throws Exception {mvc.perform(get("/cases/not-a-uuid").with(authentication(auth(client)))).andExpect(status().isBadRequest()).andExpect(header().exists("X-Correlation-ID")).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("java.")))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("SQL"))));}
@Test void tErr002ClientErrorsUseGenericCorrelatedPage() throws Exception {
 mvc.perform(put("/cases/{id}",caseRecord.getId()).with(authentication(auth(manager))).with(csrf()))
  .andExpect(status().isMethodNotAllowed()).andExpect(header().exists("Allow")).andExpect(header().exists("X-Correlation-ID")).andExpect(content().string(org.hamcrest.Matchers.containsString("Request could not be completed"))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("Exception"))));
 mvc.perform(post("/cases/{id}/evidence",caseRecord.getId()).contentType("application/xml").content("<x/>").with(authentication(auth(client))).with(csrf()))
  .andExpect(status().isUnsupportedMediaType()).andExpect(header().exists("X-Correlation-ID")).andExpect(content().string(org.hamcrest.Matchers.containsString("Request could not be completed"))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("Exception"))));
 mvc.perform(get("/cases").param("from","not-a-date").with(authentication(auth(client))))
  .andExpect(status().isBadRequest()).andExpect(header().exists("X-Correlation-ID")).andExpect(content().string(org.hamcrest.Matchers.containsString("Request could not be completed"))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("Exception"))));
 mvc.perform(get("/not-a-route").with(authentication(auth(client))))
  .andExpect(status().isNotFound()).andExpect(header().exists("X-Correlation-ID")).andExpect(content().string(org.hamcrest.Matchers.containsString("Request could not be completed"))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("Exception"))));
}
}
